package vn.covie.notifications.application; import java.util.*; import org.springframework.stereotype.Component; import vn.covie.notifications.model.NotificationType; import vn.covie.orders.model.*; import vn.covie.orders.persistence.OrderRepository; import vn.covie.outbox.application.*; import vn.covie.realtime.SseSignal;
@Component public class OrderNotificationHandler implements OutboxEventHandler {private final OrderRepository orders;private final MerchantNotificationRecipientResolver recipients;private final NotificationService notifications;public OrderNotificationHandler(OrderRepository o,MerchantNotificationRecipientResolver r,NotificationService n){orders=o;recipients=r;notifications=n;}public boolean supports(String type){return Set.of("ORDER_CREATED","ORDER_CONFIRMED","ORDER_REJECTED","ORDER_EXPIRED","ORDER_CANCELLED","ORDER_CANCELLATION_REQUESTED","ORDER_CANCELLATION_RESPONDED","ORDER_FULFILLMENT_UPDATED","ORDER_ISSUE_REPORTED","ORDER_COMPLETED","ORDER_CLOSED_WITH_ISSUE").contains(type);}public List<SseSignal> handle(OutboxEventContext event){OrderEntity order=orders.findById(event.aggregateId()).orElseThrow();NotificationType type=notificationType(event.eventType());Set<UUID> targets=targets(event.eventType(),order);List<SseSignal> signals=new ArrayList<>();Map<String,Object> data=Map.of("orderId",order.getId().toString(),"orderCode",order.getOrderCode(),"status",order.getStatus().name());for(UUID user:targets){var result=notifications.createFromOutbox(event.eventId(),user,type,"Order update","Your order status has changed.","ORDER",order.getId(),data);if(result.created())signals.add(new SseSignal(user,"notification.created",Map.of("notificationId",result.notificationId().toString())));signals.add(new SseSignal(user,"order.updated",data));}return signals;}private Set<UUID> targets(String event,OrderEntity order){Set<UUID> merchant=recipients.processorsForLocation(order.getMerchantProfileId(),order.getMerchantLocationId());return switch(event){case "ORDER_CREATED","ORDER_CANCELLATION_REQUESTED","ORDER_ISSUE_REPORTED"->merchant;case "ORDER_CONFIRMED","ORDER_REJECTED","ORDER_EXPIRED","ORDER_CANCELLATION_RESPONDED","ORDER_FULFILLMENT_UPDATED","ORDER_CLOSED_WITH_ISSUE"->Set.of(order.getBuyerUserId());case "ORDER_COMPLETED"->{Set<UUID> all=new HashSet<>(merchant);all.add(order.getBuyerUserId());yield Set.copyOf(all);}case "ORDER_CANCELLED"->switch(order.getStatus()){case CANCELLED_BY_SELLER_AFTER_CONFIRMATION->Set.of(order.getBuyerUserId());default->merchant;};default->Set.of();};}private static NotificationType notificationType(String event){return switch(event){case "ORDER_CREATED"->NotificationType.ORDER_NEW;case "ORDER_CONFIRMED"->NotificationType.ORDER_CONFIRMED;case "ORDER_REJECTED"->NotificationType.ORDER_REJECTED;case "ORDER_EXPIRED"->NotificationType.ORDER_EXPIRED;case "ORDER_CANCELLED"->NotificationType.ORDER_CANCELLED;case "ORDER_CANCELLATION_REQUESTED"->NotificationType.ORDER_CANCELLATION_REQUESTED;case "ORDER_CANCELLATION_RESPONDED"->NotificationType.ORDER_CANCELLATION_RESPONDED;case "ORDER_FULFILLMENT_UPDATED"->NotificationType.ORDER_FULFILLMENT_UPDATED;case "ORDER_ISSUE_REPORTED"->NotificationType.ORDER_ISSUE_REPORTED;case "ORDER_COMPLETED"->NotificationType.ORDER_COMPLETED;case "ORDER_CLOSED_WITH_ISSUE"->NotificationType.ORDER_CLOSED_WITH_ISSUE;default->throw new IllegalArgumentException("Unsupported order event: "+event);};}}
